"""
WardPulse shared contracts (source of truth).

Every module (engine, simulator, evaluation, API, ML) imports its data shapes
from THIS file and nowhere else. The frontend mirrors these shapes.

Rules:
  * Do not edit this file casually. A change here is a contract change:
    update docs/contracts.md in the same commit and use the commit prefix
    "contract:".
  * Keep this file free of web, database and ML imports (pure Pydantic only),
    so the engine can stay pure logic.
  * All datetimes are timezone-naive and mean ward/simulation time.
    No module may call datetime.now() inside engine code; time is always
    passed in as `now`.
  * Units: hr in bpm, sbp/dbp in mmHg, rr in breaths/min, spo2 in %,
    temp in degrees Celsius.

Import from backend/ as the working directory:
    from shared.schemas import Patient, VitalsReading, Task
"""

from datetime import datetime
from enum import Enum
from typing import Any, Dict, List, Literal, Optional

from pydantic import BaseModel, Field, computed_field, model_validator


# --------------------------------------------------------------------------
# Enums
# --------------------------------------------------------------------------

class Source(str, Enum):
    SIM = "sim"
    REPLAY = "replay"
    MANUAL = "manual"


class VitalName(str, Enum):
    HR = "hr"
    SBP = "sbp"
    DBP = "dbp"
    RR = "rr"
    SPO2 = "spo2"
    TEMP = "temp"


class Consciousness(str, Enum):
    """ACVPU scale used by NEWS2. A = alert (normal)."""
    ALERT = "A"
    CONFUSION = "C"
    VOICE = "V"
    PAIN = "P"
    UNRESPONSIVE = "U"


class Condition(str, Enum):
    """Condition tags that change a patient's expected baseline.
    Extend only through a contract change."""
    COPD = "copd"
    POST_OP = "post_op"
    CARDIAC = "cardiac"


class RiskTier(str, Enum):
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


class WardStatus(str, Enum):
    """Colour state of a bed on the ward overview strip."""
    STABLE = "stable"
    WATCH = "watch"
    ACTION = "action"
    CRITICAL = "critical"


class Mode(str, Enum):
    WARDPULSE = "wardpulse"
    NEWS2 = "news2"          # the "Naive AI" comparator


class TaskType(str, Enum):
    """CLOSED SET of cards. No free text generation, no LLM output, no drugs.
    NEWS2_ALERT is produced ONLY by engine/news2.py (naive mode)."""
    PAGE_DOCTOR = "page_doctor"
    REPEAT_BP = "repeat_bp"
    REPEAT_RESP_RATE = "repeat_resp_rate"
    REPEAT_SPO2 = "repeat_spo2"
    REPEAT_HEART_RATE = "repeat_heart_rate"
    REPEAT_TEMP = "repeat_temp"
    FULL_VITALS_RECHECK = "full_vitals_recheck"
    SIT_UPRIGHT = "sit_upright"
    CHECK_OXYGEN_CANNULA = "check_oxygen_cannula"
    NEWS2_ALERT = "news2_alert"


class TaskStatus(str, Enum):
    ACTIVE = "active"        # one of the K cards on screen (or emergency)
    QUEUED = "queued"        # waiting in the standby queue
    DONE = "done"            # nurse completed it
    DISMISSED = "dismissed"  # nurse tapped "not useful"


class StreamEventType(str, Enum):
    TASKS_UPDATED = "tasks_updated"
    WARD_UPDATED = "ward_updated"
    SIM_TICK = "sim_tick"
    EMERGENCY = "emergency"


# Display titles for the closed card set. {bed} is filled in by the engine.
# Wording must be reviewed by a clinician or nursing student before the demo.
TASK_TITLES: Dict[TaskType, str] = {
    TaskType.PAGE_DOCTOR: "Page the on-duty doctor: Bed {bed}",
    TaskType.REPEAT_BP: "Repeat manual BP: Bed {bed}",
    TaskType.REPEAT_RESP_RATE: "Recount breathing rate: Bed {bed}",
    TaskType.REPEAT_SPO2: "Recheck oxygen level: Bed {bed}",
    TaskType.REPEAT_HEART_RATE: "Recheck pulse: Bed {bed}",
    TaskType.REPEAT_TEMP: "Recheck temperature: Bed {bed}",
    TaskType.FULL_VITALS_RECHECK: "Take a full set of vitals: Bed {bed}",
    TaskType.SIT_UPRIGHT: "Sit patient upright to 45 degrees: Bed {bed}",
    TaskType.CHECK_OXYGEN_CANNULA: "Check oxygen cannula: Bed {bed}",
    TaskType.NEWS2_ALERT: "Abnormal vitals: Bed {bed}",
}

# Which vital a REPEAT_* card asks the nurse to re-measure.
TASK_TARGET_VITAL: Dict[TaskType, Optional[VitalName]] = {
    TaskType.REPEAT_BP: VitalName.SBP,
    TaskType.REPEAT_RESP_RATE: VitalName.RR,
    TaskType.REPEAT_SPO2: VitalName.SPO2,
    TaskType.REPEAT_HEART_RATE: VitalName.HR,
    TaskType.REPEAT_TEMP: VitalName.TEMP,
}


# --------------------------------------------------------------------------
# Patients and vitals
# --------------------------------------------------------------------------

class Patient(BaseModel):
    id: int
    bed: int = Field(ge=1)
    age: int = Field(ge=0, le=120)
    conditions: List[Condition] = Field(default_factory=list)
    admitted_at: datetime
    # Anonymous label only. NEVER store real names or real patient data.
    display_name: Optional[str] = None


class VitalsBase(BaseModel):
    """Any measurement may be None (not taken). Ranges below are sanity
    limits to reject typos, NOT clinical thresholds."""
    hr: Optional[float] = Field(default=None, ge=0, le=300)
    sbp: Optional[float] = Field(default=None, ge=0, le=300)
    dbp: Optional[float] = Field(default=None, ge=0, le=200)
    rr: Optional[float] = Field(default=None, ge=0, le=80)
    spo2: Optional[float] = Field(default=None, ge=0, le=100)
    temp: Optional[float] = Field(default=None, ge=25, le=45)
    on_oxygen: bool = False
    consciousness: Consciousness = Consciousness.ALERT

    @model_validator(mode="after")
    def _bp_order(self):
        if self.sbp is not None and self.dbp is not None and self.sbp < self.dbp:
            raise ValueError("sbp must be >= dbp")
        return self

    def measured(self) -> Dict[VitalName, float]:
        """Only the vitals that were actually taken."""
        out: Dict[VitalName, float] = {}
        for name in VitalName:
            value = getattr(self, name.value)
            if value is not None:
                out[name] = value
        return out


class VitalsIn(VitalsBase):
    """Body of POST /vitals. timestamp=None means 'use the simulation clock'."""
    patient_id: int
    timestamp: Optional[datetime] = None
    source: Source = Source.MANUAL

    @model_validator(mode="after")
    def _needs_a_measurement(self):
        if not self.measured():
            raise ValueError("at least one vital sign must be provided")
        return self


class VitalsReading(VitalsBase):
    """A stored reading."""
    id: int
    patient_id: int
    timestamp: datetime
    source: Source


# --------------------------------------------------------------------------
# Engine configuration (all tunable numbers live here, defaults are
# placeholders to be tuned and clinically reviewed)
# --------------------------------------------------------------------------

class EngineConfig(BaseModel):
    k_budget: int = Field(default=2, ge=1)

    # Personal baseline
    baseline_window_hours: float = 24.0
    min_baseline_readings: int = 3
    baseline_exclude_latest: int = 1       # keep a worsening patient from dragging their own "normal"
    prior_blend: float = Field(default=0.5, ge=0, le=1)  # weight on condition prior when readings are sparse

    # Risk tiers (risk_score is 0..1)
    tier_medium: float = 0.30
    tier_high: float = 0.60
    tier_critical: float = 0.85

    # Freshness: how often each tier should have vitals (hours)
    vitals_due_hours: Dict[RiskTier, float] = Field(default_factory=lambda: {
        RiskTier.LOW: 6.0,
        RiskTier.MEDIUM: 4.0,
        RiskTier.HIGH: 2.0,
        RiskTier.CRITICAL: 1.0,
    })
    stale_after_factor: float = 1.5        # stale when age > factor x due interval

    # Prioritizer
    aging_per_hour: float = 0.05           # priority added per hour a task waits
    escalation_after_minutes: float = 30.0 # ignored card gets escalated=True
    crash_bypass_enabled: bool = True

    # NEWS2 comparator
    news2_alert_threshold: int = 5         # score at or above this raises a naive alert
    news2_spo2_scale2_for_copd: bool = False  # default chart (scale 1) for everyone


# --------------------------------------------------------------------------
# Engine outputs
# --------------------------------------------------------------------------

class PatientAssessment(BaseModel):
    patient_id: int
    bed: int
    risk_score: float = Field(ge=0, le=1)
    risk_tier: RiskTier
    crash: bool = False                        # unequivocal crash vitals
    stale_vitals: List[VitalName] = Field(default_factory=list)
    hours_since_last_vitals: Optional[float] = None
    next_vitals_due: Optional[datetime] = None
    news2_score: Optional[int] = None          # filled in both modes (used by evaluation)
    reasons: List[str] = Field(default_factory=list)  # short, plain-language, nurse-readable


class Task(BaseModel):
    id: int
    patient_id: int
    bed: int
    type: TaskType
    target_vital: Optional[VitalName] = None
    title: str                                  # from TASK_TITLES
    reason: str                                 # one line, e.g. "RR 14 -> 20 over 5h; BP not taken for 7h"
    priority: float = Field(ge=0)               # higher = more urgent, includes aging
    status: TaskStatus = TaskStatus.QUEUED
    emergency: bool = False                     # crash bypass card
    escalated: bool = False                     # ignored past escalation_after_minutes
    created_at: datetime
    waiting_minutes: float = 0.0
    resolved_at: Optional[datetime] = None


class TasksResponse(BaseModel):
    mode: Mode
    now: datetime
    budget_k: Optional[int] = None              # None in naive mode (no budget)
    emergency: List[Task] = Field(default_factory=list)  # crash bypass, always on top
    active: List[Task] = Field(default_factory=list)     # at most budget_k in wardpulse mode
    queue: List[Task] = Field(default_factory=list)      # standby, ordered by priority

    @computed_field  # type: ignore[misc]
    @property
    def alerts_shown(self) -> int:
        """How many cards demand attention right now (used by the toggle demo)."""
        return len(self.emergency) + len(self.active)


class WardBed(BaseModel):
    patient_id: int
    bed: int
    conditions: List[Condition] = Field(default_factory=list)
    status: WardStatus
    risk_tier: RiskTier
    data_stale: bool = False
    hours_since_last_vitals: Optional[float] = None
    has_open_task: bool = False


class WardOverview(BaseModel):
    now: datetime
    beds: List[WardBed]


class WardEvaluation(BaseModel):
    """Return value of both engine entry points (WardPulse and NEWS2)."""
    assessments: List[PatientAssessment]
    tasks: TasksResponse
    ward: WardOverview


# --------------------------------------------------------------------------
# API shapes
# --------------------------------------------------------------------------

class PatientDetail(BaseModel):
    patient: Patient
    recent_vitals: List[VitalsReading]
    assessment: Optional[PatientAssessment] = None
    open_tasks: List[Task] = Field(default_factory=list)


class TaskFeedbackIn(BaseModel):
    note: Optional[str] = Field(default=None, max_length=500)


class AuditEntry(BaseModel):
    id: int
    timestamp: datetime
    event_type: str                             # e.g. "task_created", "task_done", "task_not_useful", "vitals_entered", "crash_bypass"
    patient_id: Optional[int] = None
    task_id: Optional[int] = None
    details: Dict[str, Any] = Field(default_factory=dict)


class SimState(BaseModel):
    running: bool
    # Simulated minutes that pass per real second. 1/60 = real time.
    speed_minutes_per_second: float = Field(default=10.0, ge=0)
    sim_time: datetime
    start_time: datetime
    scenario: str = "default"


class SimControl(BaseModel):
    action: Literal["play", "pause", "reset", "set_speed"]
    speed_minutes_per_second: Optional[float] = Field(default=None, ge=0)

    @model_validator(mode="after")
    def _speed_needed(self):
        if self.action == "set_speed" and self.speed_minutes_per_second is None:
            raise ValueError("speed_minutes_per_second is required for set_speed")
        return self


class StreamEvent(BaseModel):
    """Server-sent event. Light payload: on tasks_updated / ward_updated the
    frontend refetches GET /tasks and GET /ward. sim_tick carries SimState."""
    type: StreamEventType
    timestamp: datetime
    data: Dict[str, Any] = Field(default_factory=dict)


# --------------------------------------------------------------------------
# Evaluation
# --------------------------------------------------------------------------

class SystemMetrics(BaseModel):
    system: Mode
    events_total: int
    events_detected: int
    sensitivity: Optional[float] = None
    median_lead_time_hours: Optional[float] = None
    alerts_per_nurse_hour: Optional[float] = None
    measure_tasks_per_nurse_hour: Optional[float] = None   # WardPulse only
    false_alert_ratio: Optional[float] = None


class EvalResults(BaseModel):
    dataset: str
    sampling_interval_hours: float
    n_patients: int
    generated_at: datetime
    systems: List[SystemMetrics]
    notes: List[str] = Field(default_factory=list)
